from pathlib import Path
import json,hashlib,wave,shutil
import numpy as np
root=Path.cwd();repo=root/'work/BlackDog';out=root/'outputs/pluck-bounded-semantic-review';out.mkdir(exist_ok=True)
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
c=json.loads((repo/'docs/analysis/pluck-bounded-host-contract-2026-10-24.json').read_text());source=repo/'scripts/diagnostics/pluck-bounded-epoch.dsp';adapter=repo/'scripts/diagnostics/bounded_pluck_host_contract.py';assert sha(source)==c['source_sha256'];assert sha(adapter)==c['input_preflight']['sha256']
cases=[('release-current','bounded-pluck-release-current','solo0','capture_sha256'),('release-natural','bounded-pluck-release-natural','solo0','capture_sha256'),('capacity-eight','bounded-pluck-time-preflight-evidence','eight','sha256'),('capacity-sixteen-reference','bounded-pluck-time-preflight-evidence','sixteen','sha256'),('low-tail','bounded-pluck-history-evidence','low_tail','capture_sha256'),('rapid-history','bounded-pluck-history-evidence','rapid','capture_sha256')]
rows=[]
for name,d,label,key in cases:
 folder=root/'work'/d;r=json.loads((folder/'report.json').read_text());assert r['source_sha256']==c['source_sha256'];row=next(x for x in r['rows'] if x['sample_rate']==48000 and x['label']==label);p=folder/f'48000-{label}.bin';assert sha(p)==row[key];x=np.frombuffer(p.read_bytes(),dtype='<f4').reshape(-1,2);assert np.isfinite(x).all() and np.max(np.abs(x))<1
 pcm=np.rint(x.astype('float64')*32767).astype('<i2');wav=out/(name+'.wav')
 with wave.open(str(wav),'wb') as w:w.setnchannels(2);w.setsampwidth(2);w.setframerate(48000);w.writeframes(pcm.tobytes())
 with wave.open(str(wav),'rb') as w:assert w.getnframes()==len(x) and w.getnchannels()==2 and w.getframerate()==48000 and w.readframes(len(x))==pcm.tobytes()
 rows.append(dict(name=name,file=wav.name,wav_sha256=sha(wav),original_capture_sha256=sha(p),receipt_sha256=sha(folder/'report.json'),duration_seconds=len(x)/48000,encoding='PCM16 stereo 48kHz; nearest rounding, no normalization, gain or clipping',max_encoding_error=float(np.max(np.abs(pcm.astype('float64')/32767-x)))))
shutil.copyfile(source,out/source.name);shutil.copyfile(adapter,out/adapter.name)
packet=dict(status='AWAITING_INDEPENDENT_SEMANTIC_REVIEW',source_sha256=sha(source),adapter_sha256=sha(adapter),contract_sha256=sha(repo/'docs/analysis/pluck-bounded-host-contract-2026-10-24.json'),samples=rows,decisions={'release_and_retrigger':None,'voice_capacity_policy':None,'pitch_and_timbre':None,'integer_note_input_contract':None},reviewer=None,admission='NOT_GRANTED',pilot_ready=False,training_authorized=False)
(out/'manifest.json').write_text(json.dumps(packet,indent=2)+'\n')
(out/'README.md').write_text('''# Shipwright bounded-counter pluck semantic review\n\nStatus: pending independent review. The proposed behavior is natural decay after note-off, clean retrigger, eight voices, integer MIDI16–119 and velocity1–127. The attached exact source and adapter are bound by the manifest. This packet prepares a decision; it does not grant admission or satisfy signed readiness.\n\nListening samples use48kHz stereo PCM16 with unchanged gain and no normalization or clipping. They are listening derivatives of hash-verified float32 captures, not replacement numerical evidence. Maximum encoding error is recorded per sample.\n\n1. Compare `release-current.wav` and `release-natural.wav`: MIDI69 starts at0.01s and releases at0.21s. Both use the repaired source; the first uses the host's current dynamic voice policy, the second the proposed natural-release policy. Decide whether natural decay with clean retrigger is the intended instrument behavior.\n2. Compare `capacity-eight.wav` and `capacity-sixteen-reference.wav`: twelve notes every60ms with40ms durations. Sixteen voices are a reference only. Decide whether eight-voice tail stealing is musically acceptable, or whether the design needs a different policy.\n3. Hear `low-tail.wav` and `rapid-history.wav`: twelve-second MIDI16 decay and256 notes at25ms spacing over MIDI16/69/119/69. Assess timbre, decay and retrigger behavior. Low bass may be inaudible on phone speakers; silence on such a speaker is not evidence of failed synthesis.\n4. Review the integer-only input contract and source's20–8000Hz domain. Fractional notes are rejected rather than truncated. Sample-offset overflow and durations shorter than host resolution are rejected before host allocation.\n\nRecord decisions against the exact source, adapter and contract hashes, with reviewer identity and rationale. Leave unassessed items unresolved. This same-workflow packet is not independent review. Full-range perceptual quality, qualification beyond the documented control domain, upstream integration, canonical rights/admission, independent evaluation families and authenticated signed readiness artifacts remain outstanding.\n''')
print('Created six hash-bound listening samples',out)
